package com.autoops.credential.service;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.*;import javax.crypto.spec.*;import java.nio.charset.StandardCharsets;import java.security.SecureRandom;import java.util.Base64;@Service public class CredentialCryptoService{private final SecretKey key;public CredentialCryptoService(@Value("${autoops.credentials.key}")String raw){byte[] b=java.util.Arrays.copyOf(java.security.MessageDigestHolder.sha256(raw.getBytes(StandardCharsets.UTF_8)),32);key=new SecretKeySpec(b,"AES");}public Encrypted encrypt(String value){try{byte[] iv=new byte[12];new SecureRandom().nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(128,iv));return new Encrypted(Base64.getEncoder().encodeToString(c.doFinal(value.getBytes(StandardCharsets.UTF_8))),Base64.getEncoder().encodeToString(iv));}catch(Exception e){throw new IllegalStateException(e);}}public String decrypt(String value,String iv){try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,Base64.getDecoder().decode(iv)));return new String(c.doFinal(Base64.getDecoder().decode(value)),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException(e);}}public record Encrypted(String value,String iv){}}